values
-- 264988360_RF'Sukritacts Ingolfur Arnarson (Iceland)'CN_Add_FI
	("zh_Hans_CN",	"LOC_CIVILIZATION_SUK_ICELAND_NAME",																									"冰岛"),
	("zh_Hans_CN",	"LOC_CIVILIZATION_SUK_ICELAND_DESCRIPTION",																								"冰岛帝国"),
	("zh_Hans_CN",	"LOC_CIVILIZATION_SUK_ICELAND_ADJECTIVE",																								"冰岛的"),
	("zh_Hans_CN",	"LOC_CIVILIZATION_SUK_ICELAND_DESCRIPTION_JFD_CIVILIZATION",																			"冰岛文明"),
	("zh_Hans_CN",	"LOC_TRAIT_CIVILIZATION_SUK_SAGAS_OF_THE_ICELANDERS_NAME",																				"冰岛人萨迦"),
	("en_US",		"LOC_TRAIT_CIVILIZATION_SUK_SAGAS_OF_THE_ICELANDERS_DESCRIPTION_XP2",																	"Earn extra 2 [ICON_GREATWRITER] Great Writer point for each [ICON_GLORY_NORMAL_AGE] era score earned, and earn more more [ICON_GreatWriter] Great Writer Points as you advance through the Civics and Technology Tree. Natural Wonders, Volcanoes, Volcanic Soil and Geothermal Fissures provide +1 Appeal to adjacent tiles, and these features each provide +1 [ICON_Amenities] Amenity in the city."),
	("zh_Hans_CN",	"LOC_TRAIT_CIVILIZATION_SUK_SAGAS_OF_THE_ICELANDERS_DESCRIPTION_XP2",																	"每获得1点 [ICON_GLORY_NORMAL_AGE] 时代得分，额外获得2点[ICON_GREATWRITER] 大作家点数，随着科技与市政的研究，还将提供更多[ICON_GREATWRITER] 大作家点数。火山、火山土、地热裂缝和自然奇观单元格为相邻单元格+1魅力。城市中每有一种火山、火山土、地热裂缝和自然奇观地貌，则+1 [ICON_Amenities] 宜居度。"),
	("zh_Hans_CN",	"LOC_TRAIT_CIVILIZATION_SUK_SAGAS_OF_THE_ICELANDERS_SCIENCE",																			"+{1_num} [ICON_Science] 科技值 来自相邻 {1_Num : plural 1?自然奇观; other?自然奇观;}"),
	("zh_Hans_CN",	"LOC_TRAIT_CIVILIZATION_SUK_SAGAS_OF_THE_ICELANDERS_CULTURE",																			"+{1_num} [ICON_Culture] 文化值 来自相邻 {1_Num : plural 1?自然奇观; other?自然奇观;}"),
	("zh_Hans_CN",	"LOC_TRAIT_CIVILIZATION_SUK_SAGAS_OF_THE_ICELANDERS_GOLD",																				"+{1_num} [ICON_Gold] 金币 来自相邻 {1_Num : plural 1?自然奇观; other?自然奇观;}"),
	("zh_Hans_CN",	"LOC_TRAIT_CIVILIZATION_SUK_SAGAS_OF_THE_ICELANDERS_NOTIFICATION",																		"{1}书写了传奇来纪念历史时刻，奖励您文明{2}点 [ICON_GreatWriter] 大作家点数。"),
	("zh_Hans_CN",	"LOC_UNIT_SUK_LAWSPEAKER_NAME",																											"法律讲述官"),
	("zh_Hans_CN",	"LOC_GREAT_PERSON_CLASS_SUK_LAWSPEAKER_NAME",																											"法律讲述官"),
	("en_US",	"LOC_GREAT_PERSON_CLASS_SUK_LAWSPEAKER_NAME",																											"Lawspeaker"),
	("zh_Hans_CN",	"LOC_UNIT_SUK_LAWSPEAKER_DESCRIPTION",																									"冰岛特色伟人，在建造市政广场区域及其建筑时获得1名，首次采用某一级政府时获得1名，如果是为世界首个采用该级政体的文明，则额外获得1名。产生独特加成。"),
	("zh_Hans_CN",	"LOC_PEDIA_UNITS_PAGE_UNIT_SUK_LAWSPEAKER_CHAPTER_HISTORY_PARA_1",																		"[NEWLINE][NEWLINE]法律讲述官 (lögsögumadur) 是阿尔廷自由民议会中的高级官员。他在冰岛还没有书面文字的时候，法律讲述官的职责是在议会上背诵冰岛的法律。他们背诵议会程序的法律，主持法庭会议，并解决争端。法律讲述官被认为是在“法律岩”上向议会发表讲话的，那里是宣布判决、发表重要讲话的地方，也是议会正式开幕和解散的地方。由于旧联邦时期是冰岛社会的一个变革时期，关于权力和宗教的争端给社会和议会的工作带来了影响，所以关于议会和法律发言人的作用还有很多不清楚的地方。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_AMPHITHEATER_DUMMY",																						"若此城尚未拥有可放置 [ICON_GreatWork_Writing] 著作的古罗马剧场，则立即建成一个古罗马剧场，且额外+2 [ICON_GreatWork_Writing] 著作槽位。若非上述情况，则此城每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Culture] 文化值。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_LIBRARY_DUMMY",																								"若此城尚未拥有可放置 [ICON_GreatWork_Writing] 著作的图书馆，则立即建成一个图书馆，且额外+2 [ICON_GreatWork_Writing] 著作槽位。若非上述情况，则此城每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Science] 科技值。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_SHRINE_DUMMY",																								"若此城尚未拥有可放置 [ICON_GreatWork_Writing] 著作的神社，则立即建成一个神社，且额外+2 [ICON_GreatWork_Writing] 著作槽位。若非上述情况，则此城每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Faith] 信仰值。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_MARKET_DUMMY",																								"若此城尚未拥有可放置 [ICON_GreatWork_Writing] 著作的市场，则立即建成一个市场，且额外+2 [ICON_GreatWork_Writing] 著作槽位。若非上述情况，则此城每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Gold] 金币。"),
	("en_US",		"LOC_GREATPERSON_LAWSPEAKER_SKAFTI_THORODDSSON_ACTIVE",																					"City Center on tiles with Charming Appeal provide +1 [ICON_Culture] Culture, +1 [ICON_FOOD] Food and +1 [ICON_PRODUCTION] Production, and double on tiles with Breathtaking Appeal."),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_SKAFTI_THORODDSSON_ACTIVE",																					"位于魅力为“迷人的”单元格上的市中心+1 [ICON_CULTURE] 文化值，+1 [ICON_FOOD] 食物和+1 [ICON_PRODUCTION] 生产力，若位于惊艳单元格则翻倍。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_SNORRI_STURLUSON_ACTIVE",																					"每次招募一位 [ICON_GreatWriter] 大作家可奖励 [ICON_Culture] 文化值。[ICON_GreatWork_Writing] 著作额外+50% [ICON_Culture] 文化值。"),
	("en_US",		"LOC_GREATPERSON_LAWSPEAKER_ULFLJOTR_ACTIVE",																							"Torfbæir on tiles with Charming Appeal provide +2 [ICON_Culture] Culture and +2 [ICON_GreatWriter] Great Writer Points, and double on tiles with Breathtaking Appeal."),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_ULFLJOTR_ACTIVE",																							"位于魅力为“迷人的”单元格上的草屋提供+2 [ICON_Culture] 文化值，+2 [ICON_GreatWriter] 大作家点数，若位于惊艳单元格则翻倍。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_HRAFN_HAENGSSON_ACTIVE",																					"该剧院广场的 [ICON_Culture] 文化值相邻加成翻倍。所在城市的每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Culture] 文化值。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_THORGEIR_LJOSVETNINGAGODI_ACTIVE",																			"每次招募一位 [ICON_GreatWriter] 大作家可奖励 [ICON_Faith] 信仰值。所在城市的每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Faith] 信仰值。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_OLAFR_THORTHARSON_ACTIVE",																					"该剧院广场可提供等同于自身 [ICON_Culture] 文化值相邻加成的 [ICON_Science] 科技值。所在城市的每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Science] 科技值。"),
	("zh_Hans_CN",	"LOC_GREATPERSON_LAWSPEAKER_MARKUS_SKEGGJASON_ACTIVE",																					"每次招募一位 [ICON_GreatWriter] 大作家可奖励 [ICON_Gold] 金币。所在城市的每本 [ICON_GreatWork_Writing] 著作可奖励{Amount} [ICON_Gold] 金币。"),
	("zh_Hans_CN",	"LOC_ABILITY_SUK_LAWSPEAKER_RECRUIT_WRITER_MESSAGE",																					"{1_Bonus} 来自于招募大作家“{2_WriterName}”的奖励"),
	("zh_Hans_CN",	"LOC_ABILITY_SUK_LAWSPEAKER_RECRUIT_WRITER_SUBMESSAGE",																					"{3_Color}+{1_num}[ENDCOLOR] {2_FontIcon}"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_NAME",																										"草屋"),
	("en_US",		"LOC_DISTRICT_SUK_TORFBAEIR_XP2_DESCRIPTION",																							"A district unique to Iceland, replacing the Aqueduct district. Unlock in Early Empire civic.[NEWLINE][NEWLINE]Instead of the Aqueduct's usual restrictions and bonuses, Torfbæir provide +2 [ICON_Housing] Housing, +1 [ICON_Food] Food, +1 [ICON_Production] Production. Increases to +3 [ICON_Housing], +2 [ICON_Food], +2 [ICON_Production], on Charming tiles, or to +4 [ICON_Housing], +3 [ICON_Food], +3 [ICON_Production] on Breathtaking tiles. No adjacency bonus to Industrial Zones.[NEWLINE][NEWLINE]+1 [ICON_Amenities] Amenity if built on a Geothermal Fissure or Volcanic Soil.+1 Appeal to adjacent tiles. Prevents [ICON_Food] Food loss during Drought. Cannot be built on Desert tiles."),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_XP2_DESCRIPTION",																							"冰岛特色区域，取代蓄水池。[NEWLINE][NEWLINE]取消了通常的限制和加成，提供+2 [ICON_Housing] 住房、+1 [ICON_Food] 食物、+1 [ICON_Production] 生产力；建造在魅力为“迷人的”单元格上时，提升至+3 [ICON_Housing] 住房、+2 [ICON_Food] 食物、+2 [ICON_Production] 生产力；建造在魅力为“惊艳的”单元格上时，提升至+4 [ICON_Housing] 住房、+3 [ICON_Food] 食物、+3 [ICON_Production] 生产力。为相邻单元格+1魅力。建造在火山土或地热裂缝上+1 [ICON_AMENITIES] 宜居度。不能建造在沙漠上。"),
	("en_US",		"LOC_DISTRICT_SUK_TORFBAEIR_XP2_FRONTEND_DESCRIPTION",																					"A district unique to Iceland, replacing the Aqueduct district. Unlock in Early Empire civic.[NEWLINE][NEWLINE]Instead of the Aqueduct's usual restrictions and bonuses, Torfbæir provide +2 [ICON_Housing] Housing, +1 [ICON_Food] Food, +1 [ICON_Production] Production. Increases to +3 [ICON_Housing], +2 [ICON_Food], +2 [ICON_Production], on Charming tiles, or to +4 [ICON_Housing], +3 [ICON_Food], +3 [ICON_Production] on Breathtaking tiles. No adjacency bonus to Industrial Zones.[NEWLINE][NEWLINE]+1 [ICON_Amenities] Amenity if built on a Geothermal Fissure or Volcanic Soil.+1 Appeal to adjacent tiles. Prevents [ICON_Food] Food loss during Drought. Cannot be built on Desert tiles."),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_XP2_FRONTEND_DESCRIPTION",																					"冰岛特色区域，取代蓄水池，[NEWLINE][NEWLINE]取消了通常的限制和加成，提供+2 [ICON_Housing] 住房、+1 [ICON_Food] 食物、+1 [ICON_Production] 生产力；建造在魅力为“迷人的”单元格上时，提升至+3 [ICON_Housing] 住房、+2 [ICON_Food] 食物、+2 [ICON_Production] 生产力；建造在魅力为“惊艳的”单元格上时，提升至+4 [ICON_Housing] 住房、+3 [ICON_Food] 食物、+3 [ICON_Production] 生产力。为相邻单元格+1魅力。建造在火山土或地热裂缝上+1 [ICON_AMENITIES] 宜居度。不能建造在沙漠上。"),
	("zh_Hans_CN",	"LOC_PEDIA_DISTRICTS_PAGE_DISTRICT_SUK_TORFBAEIR_CHAPTER_HISTORY_PARA_1",																"[NEWLINE][NEWLINE]当看到冰岛的图片时，一定会出现看起来小巧可爱的草屋（Torfbæir）。由于冰岛缺乏树木，用草皮建造是一种流行的建筑材料，厚厚的草皮墙对抵御寒冷很有用。这种用草皮建筑的技术最早出现在9至11世纪欧洲维京时代的巅峰时期，随着北欧和不列颠定居者的到来而产生。历史记录表明，直到19世纪末，多达50%的冰岛住宅是由草皮构建构成的，尽管这一数字在20世纪开始下降。到1960年，冰岛有234个有人居住的草皮住宅，其中大部分在接下来的十年中被遗弃。"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_BASE_FOOD",																									"+{1_num} [ICON_Food] 食物"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_BASE_PRODUCTION",																							"+{1_num} [ICON_Production] 生产力"),
	("en_US",		"LOC_DISTRICT_SUK_TORFBAEIR_APPEAL_PRODUCTION",																							"+{1_num} [ICON_Production] Production from the tile's Appeal."),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_APPEAL_PRODUCTION",																							"+{1_num} [ICON_Production] 生产力 来自 单元格魅力"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_APPEAL_FOOD",																								"+{1_num} [ICON_Food] 食物 来自 单元格魅力"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_APPEAL_CULTURE",																							"+{1_num} [ICON_Culture] 文化值 来自 单元格魅力"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_APPEAL_HOUSING_BASE",																						"无吸引力及更差的"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_APPEAL_HOUSING_CHARMING",																					"迷人的"),
	("zh_Hans_CN",	"LOC_DISTRICT_SUK_TORFBAEIR_APPEAL_HOUSING_BREATHTAKING",																				"惊艳的"),
	("zh_Hans_CN",	"LOC_LEADER_SUK_INGOLFUR_NAME",																											"殷格·亚纳逊"),
	("zh_Hans_CN",	"LOC_TRAIT_LEADER_SUK_BOOK_OF_SETTLEMENTS_NAME",																						"定居书"),
	("en_US",		"LOC_TRAIT_LEADER_SUK_BOOK_OF_SETTLEMENTS_XP2_DESCRIPTION",																				"Settlers and Recon units receive +1 [ICON_Movement] Movement, +1 Sight. Recon units can escort moving civilian and support units at their [ICON_MOVEMENT] Movement speed. Cities on tiles with Charming Appeal or better receive Loyalty equal to the tile’s Appeal. When placing a district on a tile with Breathtaking Appeal, receive a burst of [ICON_Production] Production towards that district."),
	("zh_Hans_CN",	"LOC_TRAIT_LEADER_SUK_BOOK_OF_SETTLEMENTS_XP2_DESCRIPTION",																				"开拓者和侦查单位+1 [ICON_MOVEMENT] 移动力并+1视野范围。侦查单位可利用自身的 [ICON_MOVEMENT] 移动力护送平民和支援单位。建造在迷人以上单元格的城市获得额外的忠诚度，等于其市中心所在单元格的魅力。建造在惊艳单元格的区域直接获得33%建造进度。"),
	("zh_Hans_CN",	"LOC_TRAIT_LEADER_SUK_BOOK_OF_SETTLEMENTS_MESSAGE",																						"[COLOR_FLOAT_PRODUCTION]+{1_num}[ENDCOLOR] [ICON_Production]"),
	("zh_Hans_CN",	"LOC_UNIT_SUK_BOOK_OF_SETTLEMENTS_DESCRIPTION",																							"+1 [ICON_Movement] 移动力，+1视野。（{LOC_TRAIT_LEADER_SUK_BOOK_OF_SETTLEMENTS_NAME}）"),
	("zh_Hans_CN",	"LOC_SUK_BOOK_OF_SETTLEMENTS_APPEAL_DISTRICT_CAMPUS",																					"+{1_num} [ICON_Science] 科技值 来自 单元格魅力"),
	("zh_Hans_CN",	"LOC_SUK_BOOK_OF_SETTLEMENTS_APPEAL_DISTRICT_THEATER",																					"+{1_num} [ICON_Culture] 文化值 来自 单元格魅力"),
	("zh_Hans_CN",	"LOC_SUK_BOOK_OF_SETTLEMENTS_APPEAL_DISTRICT_COMMERCIAL_HUB",																			"+{1_num} [ICON_Gold] 金币 来自 单元格魅力"),
	("zh_Hans_CN",	"LOC_SUK_BOOK_OF_SETTLEMENTS_APPEAL_DISTRICT_HOLY_SITE",																				"+{1_num} [ICON_Faith] 信仰值 来自 单元格魅力"),
	("zh_Hans_CN",	"LOC_AGENDA_SUK_BAY_OF_SMOKE_NAME",																										"雷克雅未克"),
	("zh_Hans_CN",	"LOC_AGENDA_SUK_BAY_OF_SMOKE_DESCRIPTION",																								"喜欢积极探索地图和定居在自然奇观附近的文明，厌恶对探索不感兴趣的文明。"),
	("zh_Hans_CN",	"LOC_DIPLO_KUDO_LEADER_SUK_INGOLFUR_REASON_ANY",																						"（您拥有自然奇观，并正在探索地图）"),
	("zh_Hans_CN",	"LOC_DIPLO_MODIFIER_SUK_BAY_OF_SMOKE_KUDO",																								"英格尔夫欣赏你的自然奇观和冒险精神。"),
	("zh_Hans_CN",	"LOC_DIPLO_WARNING_LEADER_SUK_INGOLFUR_REASON_ANY",																						"（您没有探索地图）"),
	("zh_Hans_CN",	"LOC_DIPLO_MODIFIER_SUK_BAY_OF_SMOKE_WARNING",																							"你缺乏对探索的兴趣，英格尔夫感到失望。"),
